package dev.starfold;
import dev.starfold.BentStripGeometry.Point;
import dev.starfold.CubeSurfaceTopology.Face;
import net.minecraft.network.RegistryFriendlyByteBuf;
import org.joml.Quaterniond;
import org.junit.jupiter.api.*;
import java.nio.file.*;
import static org.junit.jupiter.api.Assertions.*;

/** Wire and live-binding contracts. Does not launch the Minecraft server or renderer. */
class NativeGroundFlightRuntimeTest {
    @BeforeAll static void registry(){net.minecraft.SharedConstants.tryDetectVersion();net.minecraft.server.Bootstrap.bootStrap();}
    NativeGroundDynamics.State local(double h){return NativeGroundDynamics.local(900,new NativeGroundTopology.Pose(Face.TOP,new Point(1024,h,1024)),new Point(.1,.3,.05),new Quaterniond(),true,NativeGroundDynamics.OFF);}
    String source(String n)throws Exception{return Files.readString(Path.of("src/main/java/dev/starfold/"+n+".java"));}
    @Test void farFromEveryPlanetAHeldVesselCruisesAndCanStillStopBeforeTheNext(){
        assertEquals(UniverseMotion.speed(500,true),NativeGroundDynamics.cruise(500,true));assertEquals(UniverseMotion.speed(1024,true),NativeGroundDynamics.cruise(1024,true));assertEquals(80,NativeGroundDynamics.cruise(1600,true),1e-9);assertEquals(NativeGroundDynamics.CRUISE,NativeGroundDynamics.cruise(60000,true));
        for(double h:new double[]{0,300,5000,60000})assertEquals(UniverseMotion.speed(h,false),NativeGroundDynamics.cruise(h,false));
        double v=NativeGroundDynamics.CRUISE,h=60000;while(h>1100){double want=NativeGroundDynamics.cruise(h,true);v=v>want?Math.max(want,v-GroundTransit.ACCEL):want;h-=v;assertTrue(v<=NativeGroundDynamics.cruise(h+v,true)+1e-9);}
        assertTrue(v<=70&&h>1000,v+" "+h);
    }
    @Test void setupAndAuthoritativeStateCarryEpochMaskGuidanceAndOwnership(){var raw=io.netty.buffer.Unpooled.buffer();try{var b=new RegistryFriendlyByteBuf(raw,net.minecraft.core.RegistryAccess.EMPTY);var model=GroundSolar.defaults();var s=NativeGroundDynamics.detach(model,local(6000));var setup=new NativeGroundFlightPackets.Setup(42,model,new GroundSpace.Config(16,128),s,true);NativeGroundFlightPackets.Setup.CODEC.encode(b,setup);assertEquals(setup,NativeGroundFlightPackets.Setup.CODEC.decode(b));var state=new NativeGroundFlightPackets.State(42,9,s,true);NativeGroundFlightPackets.State.CODEC.encode(b,state);assertEquals(state,NativeGroundFlightPackets.State.CODEC.decode(b));assertEquals(0,b.readableBytes());}finally{raw.release();}}
    @Test void inputAndResyncWireCannotPlaceBlocksOrAddressInventory(){var raw=io.netty.buffer.Unpooled.buffer();try{var b=new RegistryFriendlyByteBuf(raw,net.minecraft.core.RegistryAccess.EMPTY);var motion=new PlanetMotion.Input(1,0,0,0,1,1,-1,.5f,true,true);var p=new NativeGroundFlightPackets.Input(42,motion,true);NativeGroundFlightPackets.Input.CODEC.encode(b,p);assertEquals(p,NativeGroundFlightPackets.Input.CODEC.decode(b));var sync=new NativeGroundFlightPackets.Sync(42);NativeGroundFlightPackets.Sync.CODEC.encode(b,sync);assertEquals(sync,NativeGroundFlightPackets.Sync.CODEC.decode(b));assertEquals(0,b.readableBytes());assertEquals(3,NativeGroundFlightPackets.Input.class.getRecordComponents().length);}finally{raw.release();}}
    @Test void invalidOwnershipAndEmptySessionsAreRejected(){var model=GroundSolar.defaults();var space=NativeGroundDynamics.detach(model,local(6000));assertThrows(IllegalArgumentException.class,()->new NativeGroundFlightPackets.Setup(0,model,GroundSpace.DEFAULT_MASK,space,true));assertThrows(IllegalArgumentException.class,()->new NativeGroundFlightPackets.Setup(42,model,GroundSpace.DEFAULT_MASK,space,false));assertThrows(IllegalArgumentException.class,()->new NativeGroundFlightPackets.State(42,0,local(100),true));assertThrows(IllegalArgumentException.class,()->new NativeGroundFlightPackets.State(42,-1,space,true));assertThrows(IllegalArgumentException.class,()->new NativeGroundFlightPackets.Input(42,PlanetMotion.Input.idle(0,new Quaterniond()),false));}
    NativeGroundFlightPackets.Input input(long n,boolean toggle){return new NativeGroundFlightPackets.Input(42,PlanetMotion.Input.idle(n,new Quaterniond()),toggle);}
    @Test void boundedOrderedQueueConsumesGOnceAndRejectsReplayBurstAndSkippedSequence(){var q=new NativeGroundFlightPackets.Queue();assertFalse(q.offer(input(2,false),0));assertTrue(q.offer(input(1,true),0));assertFalse(q.offer(input(1,true),0));assertTrue(q.offer(input(2,false),0));assertTrue(q.offer(input(3,false),0));assertTrue(q.offer(input(4,false),0));assertFalse(q.offer(input(5,false),0));assertTrue(q.offer(input(5,false),1));assertTrue(q.poll().toggle());for(int i=0;i<4;i++)assertFalse(q.poll().toggle());assertNull(q.poll());assertEquals(5,q.ack());for(int i=6;i<30;i++)assertTrue(q.offer(input(i,false),i));assertFalse(q.offer(input(30,false),30));}
    @Test void serverWorldTickEntryLeaveAndSpinUseTheFlightAdapter()throws Exception{String server=source("NativeGroundServer");assertTrue(server.contains("NativeGroundFlightServer.tick(level,saved)"));assertTrue(server.contains("NativeGroundFlightServer.entry(player,level,clock)"));assertTrue(server.indexOf("NativeGroundFlightServer.entry(player,level,clock)")<server.indexOf("LabSave.get(NativePlanetSystem.authority(level)).remember(player)"));assertTrue(server.contains("NativeGroundFlightServer.enter(player,clock,saved)"));assertTrue(server.contains("NativeGroundFlightServer.detach(player)"));assertTrue(server.contains("NativeGroundFlightServer.restart(player,clock)"));String flight=source("NativeGroundFlightServer");assertTrue(flight.contains("NativeGroundNavigationSave.get"));assertTrue(flight.contains("new NativeGroundTerrain"));assertFalse(flight.contains("GroundWorld"));assertTrue(flight.contains("getChunkSource().move(player)"));}
    @Test void registeredMixinSelectorsProtectOnlyTheVesselAndLeaveVanillaGround()throws Exception{var json=com.google.gson.JsonParser.parseString(Files.readString(Path.of("src/main/resources/starfold.mixins.json"))).getAsJsonObject();for(String n:new String[]{"NativeGroundFlightTravelMixin","NativeGroundFlightNetworkMixin"})assertTrue(json.getAsJsonArray("mixins").asList().stream().anyMatch(x->x.getAsString().equals(n)));for(String n:new String[]{"NativeGroundFlightClientMovementMixin","NativeGroundFlightCameraMixin","NativeGroundFlightMouseMixin","NativeGroundFlightRenderMixin"})assertTrue(json.getAsJsonArray("client").asList().stream().anyMatch(x->x.getAsString().equals(n)));assertTrue(source("mixin/NativeGroundFlightTravelMixin").contains("NativeGroundFlightServer.controlled(e)"));assertTrue(source("mixin/NativeGroundFlightClientMovementMixin").contains("NativeGroundFlightClient.controlled()"));assertTrue(source("NativeGroundClient").contains("NativeGroundFlightClient.initialize(modBus)"));assertTrue(source("NativeGroundFlightClient").contains("pending.size()>=24"));assertTrue(source("NativeGroundFlightClient").contains("OrbitAttitude.turn"));}
    @Test void nativeMaskMetadataRoundTripsWithoutReplacingOriginalSkyModel(){var saved=NativeGroundClock.fresh(false);saved.mask=new GroundSpace.Config(24,256);var tag=saved.save(new net.minecraft.nbt.CompoundTag(),null);var copy=NativeGroundClock.load(tag,null);assertEquals(saved.mask,copy.mask);assertEquals(saved.clock.model,copy.clock.model);tag.remove("native_mask");assertEquals(GroundSpace.DEFAULT_MASK,NativeGroundClock.load(tag,null).mask);tag.putInt("native_mask",1);assertThrows(IllegalArgumentException.class,()->NativeGroundClock.load(tag,null));}
}
